  const STORAGE = 'trx_2prep_ultimate_v1';
  const USER_STORAGE = 'trx_2prep_user_v1';
  const SOUND_STORAGE = 'trx_2prep_sound_v1';
  const DEFAULT_STATE = {
    xp: 0,
    solved: 0,
    correct: 0,
    streak: 0,
    lastDate: null,
    completedLessons: [],
    mistakes: [],
    daily: { q: false, l: false, m: false },
    bossCount: 0,
    completedUnits: []
  };

  let state = loadState();
  let currentUser = loadUser();
  let soundOn = localStorage.getItem(SOUND_STORAGE) !== 'off';
  let selectedUnit = 1;
  let selectedLesson = 1;
  let lessonTab = 'overview';
  let quiz = null;
  let audioCtx = null;

  const $ = (s, root=document) => root.querySelector(s);
  const $$ = (s, root=document) => [...root.querySelectorAll(s)];

  function loadState() {
    try { return normalizeState(JSON.parse(localStorage.getItem(STORAGE) || 'null') || DEFAULT_STATE); }
    catch { return normalizeState(DEFAULT_STATE); }
  }
  function normalizeState(s) {
    return {
      ...DEFAULT_STATE,
      ...s,
      completedLessons: Array.isArray(s.completedLessons) ? s.completedLessons : [],
      mistakes: Array.isArray(s.mistakes) ? s.mistakes : [],
      completedUnits: Array.isArray(s.completedUnits) ? s.completedUnits : [],
      daily: { ...DEFAULT_STATE.daily, ...(s.daily || {}) }
    };
  }
  function saveState(){ localStorage.setItem(STORAGE, JSON.stringify(state)); }
  function loadUser(){ try{return JSON.parse(localStorage.getItem(USER_STORAGE)||'null')}catch{return null} }
  function saveUser(user){currentUser=user;localStorage.setItem(USER_STORAGE,JSON.stringify(user));}
  function todayKey(){const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
  function updateStreak(){
    const today=todayKey();
    if(!state.lastDate){state.streak=1;state.lastDate=today;saveState();return}
    if(state.lastDate===today) return;
    const old=new Date(state.lastDate); const now=new Date(today);
    const days=Math.round((now-old)/86400000);
    state.streak=days===1 ? state.streak+1 : 1;
    state.lastDate=today; saveState();
  }
  function initials(name){ return (name||'Student').split(/\s+/).map(x=>x[0]).join('').slice(0,2).toUpperCase(); }
  function escapeHtml(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]))}
  function level(){return Math.floor(state.xp/100)+1}
  function levelXP(){return state.xp%100}
  function accuracy(){return state.solved?Math.round(state.correct/state.solved*100):0}
  function unitProgress(unit){
    const unitQs=COURSE.questions.filter(q=>q.unit===unit);
    const lessons=COURSE.lessons.find(x=>x.unit===unit)?.lessons || [];
    if(!lessons.length) return 0;
    const done=lessons.filter(l=>state.completedLessons.includes(l.id)).length;
    return Math.round(done/lessons.length*100);
  }
  function playTone(freq,duration=0.08,type='sine',volume=0.045,when=0){
    if(!soundOn) return;
    try{
      audioCtx = audioCtx || new (window.AudioContext||window.webkitAudioContext)();
      const o=audioCtx.createOscillator(), g=audioCtx.createGain();
      o.type=type;o.frequency.value=freq;g.gain.setValueAtTime(volume,audioCtx.currentTime+when);g.gain.exponentialRampToValueAtTime(0.0001,audioCtx.currentTime+when+duration);
      o.connect(g);g.connect(audioCtx.destination);o.start(audioCtx.currentTime+when);o.stop(audioCtx.currentTime+when+duration);
    }catch{}
  }
  function sound(name){
    if(!soundOn) return;
    if(name==='click') playTone(430,0.045,'sine',0.025);
    if(name==='correct'){playTone(660,0.08,'sine',0.04);playTone(880,0.11,'sine',0.035,0.08)}
    if(name==='wrong'){playTone(180,0.12,'triangle',0.035);playTone(130,0.12,'triangle',0.03,0.07)}
    if(name==='level'){playTone(523,0.08,'sine',0.04);playTone(659,0.08,'sine',0.04,0.08);playTone(784,0.14,'sine',0.04,0.16)}
    if(name==='win'){playTone(523,0.1,'sine',0.045);playTone(659,0.1,'sine',0.045,0.08);playTone(784,0.1,'sine',0.045,0.16);playTone(1046,0.25,'sine',0.045,0.24)}
  }
  function flashToast(text, kind=''){const t=document.createElement('div');t.className='toast '+kind;t.textContent=text;$('#toastStack').appendChild(t);setTimeout(()=>t.remove(),2600)}
  function playConfetti(){
    const host=$('#confetti');host.innerHTML='';
    for(let i=0;i<54;i++){const p=document.createElement('span');p.className='confetti-piece';p.style.left=Math.random()*100+'%';p.style.setProperty('--x',(Math.random()*220-110)+'px');p.style.animationDelay=(Math.random()*.45)+'s';p.style.background=['#6d4aff','#19b978','#ff9c3d','#3e84ff','#eb5573'][i%5];p.style.transform=`rotate(${Math.random()*80}deg)`;host.appendChild(p)}
  }
