  function lessonVideoSearch(u,l){return 'https://www.youtube.com/results?search_query='+encodeURIComponent(`الخطة التعليمية الثاني الإعدادي English Unit ${u} ${l}`)}
  function youtubeWatch(id){return `https://www.youtube.com/watch?v=${encodeURIComponent(id)}`}
