    $$('.lesson-tab[data-tab]').forEach(b=>b.addEventListener('click',()=>{lessonTab=b.dataset.tab;renderLessonView()}));
    $('#closeLesson').addEventListener('click',()=>$('#lessonView').classList.add('hidden'));
